use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::Array(arr) = input {
        if arr.len() < 2 {
            return Value::Array(vec![]);
        }

        let mut result = Vec::new();
        let mut prev = 0;
        for item in arr {
            let num = item.as_i64().unwrap();
            let diff = num - prev;
            result.push(Value::Number(diff.into()));
            prev = num;
        }
        Value::Array(result)
    } else {
        Value::Array(vec![])
    }
}
